<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/crypto.php';require_once __DIR__.'/../lib/upload.php';
send_cors_headers();$principal=require_principal(['influencer']);$id=$principal['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->prepare('SELECT id,full_name,email,mobile,handle,bio,platforms_json,audience_json,status,verification_status FROM influencers WHERE id=:id');$stmt->execute(['id'=>$id]);$profile=$stmt->fetch();$documents=$db->prepare('SELECT d.id,d.document_type,d.verification_status,d.rejection_reason,f.scan_status,f.id AS file_id FROM influencer_documents d JOIN file_assets f ON f.id=d.file_asset_id WHERE d.influencer_id=:id AND f.deleted_at IS NULL');$documents->execute(['id'=>$id]);$payout=$db->prepare('SELECT beneficiary_name,account_last4,pan_last4,verification_status FROM influencer_payout_profiles WHERE influencer_id=:id');$payout->execute(['id'=>$id]);json_response(200,['success'=>true,'profile'=>$profile,'documents'=>$documents->fetchAll(),'payout_profile'=>$payout->fetch()?:null]);}
if($method==='PATCH'){
    $body=get_json_body();
    $bio=trim((string)($body['bio']??''));
    $platforms=$body['platforms']??[];
    $audience=$body['audience']??[];
    if(mb_strlen($bio)<40||mb_strlen($bio)>2000||!is_array($platforms)||count($platforms)<1||count($platforms)>5||!is_array($audience)||mb_strlen((string)($audience['region']??''))>100)
        json_response(422,['success'=>false,'message'=>'Enter a detailed bio and one to five valid social platforms.']);
    foreach($platforms as $platform){
        if(!is_array($platform)||mb_strlen(trim((string)($platform['name']??'')))<2||mb_strlen((string)$platform['name'])>50||!filter_var($platform['url']??'',FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url((string)$platform['url'],PHP_URL_SCHEME)),['https','http'],true)||filter_var($platform['followers']??null,FILTER_VALIDATE_INT)===false||(int)$platform['followers']<0)
            json_response(422,['success'=>false,'message'=>'Check each social platform URL and follower count.']);
    }
    $current=$db->prepare('SELECT status FROM influencers WHERE id=:id LIMIT 1');$current->execute(['id'=>$id]);$status=$current->fetchColumn();
    if(!in_array($status,['application_draft','changes_requested','pending_review','active'],true))json_response(409,['success'=>false,'message'=>'This profile cannot be edited in its current state.']);
    $next=$status==='active'?'pending_review':$status;
    $db->prepare('UPDATE influencers SET bio=:bio,platforms_json=:platforms,audience_json=:audience,status=:status,verification_status=IF(:review="pending_review","submitted",verification_status),updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['bio'=>$bio,'platforms'=>json_encode($platforms,JSON_UNESCAPED_SLASHES),'audience'=>json_encode($audience,JSON_UNESCAPED_SLASHES),'status'=>$next,'review'=>$next,'id'=>$id]);
    if($status==='active')record_status_change('influencer',$id,'active','pending_review','Public profile updated; reapproval required.');
    json_response(200,['success'=>true,'message'=>$status==='active'?'Profile saved and sent for admin re-review. Public listing pauses until approval.':'Creator profile saved.']);
}
if($method==='POST'){$action=trim((string)($_GET['action']??''));if($action==='upload'){$type=trim((string)($_POST['document_type']??''));if(!in_array($type,['identity','pan','address','social_ownership'],true)||!isset($_FILES['document']))json_response(422,['success'=>false,'message'=>'Valid document type and file are required.']);$asset=store_private_upload($_FILES['document'],'influencer',$id,'influencer_'.$type,['image/jpeg','image/png','application/pdf'],5*1024*1024);$docId=uuid_string();$db->prepare('INSERT INTO influencer_documents (id,influencer_id,document_type,file_asset_id,verification_status,created_at,updated_at) VALUES (:id,:owner,:type,:file,"pending",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$docId,'owner'=>$id,'type'=>$type,'file'=>$asset['id']]);json_response(201,['success'=>true,'message'=>'Document uploaded and queued for scanning.','document_id'=>$docId]);}if($action==='payout'){$body=get_json_body();$beneficiary=trim((string)($body['beneficiary_name']??''));$account=preg_replace('/\D+/','',(string)($body['account_number']??''));$ifsc=strtoupper(trim((string)($body['ifsc']??'')));$pan=strtoupper(trim((string)($body['pan']??'')));if(mb_strlen($beneficiary)<2||strlen($account)<9||strlen($account)>18||!preg_match('/^[A-Z]{4}0[A-Z0-9]{6}$/',$ifsc)||!preg_match('/^[A-Z]{5}[0-9]{4}[A-Z]$/',$pan))json_response(422,['success'=>false,'message'=>'Bank, IFSC or PAN details are invalid.']);$db->prepare('INSERT INTO influencer_payout_profiles (influencer_id,beneficiary_name,account_number_encrypted,account_last4,ifsc_encrypted,pan_encrypted,pan_last4,verification_status,updated_at) VALUES (:id,:name,:account,:last4,:ifsc,:pan,:pan4,"pending",UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE beneficiary_name=VALUES(beneficiary_name),account_number_encrypted=VALUES(account_number_encrypted),account_last4=VALUES(account_last4),ifsc_encrypted=VALUES(ifsc_encrypted),pan_encrypted=VALUES(pan_encrypted),pan_last4=VALUES(pan_last4),verification_status="pending",updated_at=UTC_TIMESTAMP()')->execute(['id'=>$id,'name'=>$beneficiary,'account'=>encrypt_sensitive($account),'last4'=>substr($account,-4),'ifsc'=>encrypt_sensitive($ifsc),'pan'=>encrypt_sensitive($pan),'pan4'=>substr($pan,-4)]);json_response(200,['success'=>true,'message'=>'Payout profile saved for verification.']);}if($action==='submit'){$profile=$db->prepare('SELECT * FROM influencers WHERE id=:id FOR UPDATE');$profile->execute(['id'=>$id]);$creator=$profile->fetch();if(!$creator||!in_array($creator['status'],['application_draft','changes_requested'],true))json_response(409,['success'=>false,'message'=>'This application cannot be submitted in its current state.']);$docs=$db->prepare('SELECT document_type,MAX(CASE WHEN verification_status<>"rejected" THEN 1 ELSE 0 END) valid FROM influencer_documents d JOIN file_assets f ON f.id=d.file_asset_id WHERE d.influencer_id=:id AND f.scan_status="clean" GROUP BY document_type');$docs->execute(['id'=>$id]);$types=array_column(array_filter($docs->fetchAll(),fn($document)=>(int)$document['valid']===1),'document_type');if(mb_strlen((string)$creator['bio'])<40||!in_array('identity',$types,true)||!in_array('pan',$types,true)||!in_array('social_ownership',$types,true))json_response(422,['success'=>false,'message'=>'Complete the profile and upload clean identity, PAN and social ownership documents.']);$db->prepare('UPDATE influencers SET status="pending_review",verification_status="submitted",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$id]);record_status_change('influencer',$id,$creator['status'],'pending_review');json_response(200,['success'=>true,'message'=>'Creator application submitted for review.']);}}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
